# Class 4 (age 9-10): standing on one's own ground. The Mahabharata (in place of the Norse myths of
# European Waldorf schools) with its strong, flawed heroes; maps from home outwards; the human being
# and the animal; fractions breaking the whole; tenses and letter writing.

STORY4_PRACTICE = [("Recite", "Recite the month's poem with clear speech; a verse from the Gita or a Rabindranath Tagore poem."),
                   ("Composition", "Write three sentences about yesterday's story in your own words, then read them aloud."),
                   ("Dictation", "Dictate a short paragraph from the story; check spelling together.")]
GEO_PRACTICE = [("Compass walk", "Walk outside and point north, south, east and west using the sun."),
                ("Map detective", "Find two places on a printed map of your city or state."),
                ("Measure and scale", "Measure one room and draw it at 1 cm for 1 step.")]
ZOO_PRACTICE = [("Observe", "Watch a real animal (cat, dog, cow, bird, insect) for five minutes and note three things."),
                ("Animal riddles", "Make a riddle about today's animal for the family to guess."),
                ("Clay model", "Model today's animal in beeswax or clay.")]
FRAC_PRACTICE = [("Fraction kitchen", "Cut a roti, chapati or fruit into halves, quarters, thirds."),
                 ("Tables", "Mixed tables to 12 with a ball."),
                 ("Mental maths", "Five quick fraction questions: half of 20, a quarter of 12…")]

